(()=>{let requested=false,virtual=false;const $=s=>document.querySelector(s);
function switchMode(on){virtual=on;if($('#source-drawer').open)$('#source-drawer').close();document.body.classList.toggle('virtual-mode',on);document.querySelectorAll('[data-world]').forEach(b=>b.setAttribute('aria-pressed',String((b.dataset.world==='virtual')===on)));window.realityMode?.(!on);if(on&&!requested){requested=true;import('./twin.js').catch(error=>{$('#twin-stage').textContent='3D 엔진 로딩 실패 · 인터넷/WebGL 확인 후 페이지를 새로고침하세요.';console.error(error);});}window.twinScene?.activate(on);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(b?.dataset.world)switchMode(b.dataset.world==='virtual');if(b?.id==='logout')window.twinScene?.activate(false);if(b?.id==='ops-direct'&&virtual)window.twinScene?.activate(true);});$('#login-card').addEventListener('submit',()=>{if(virtual)window.twinScene?.activate(true);});window.addEventListener('twin-ready',()=>window.twinScene.activate(virtual&&!document.body.classList.contains('locked')));
})();
